"""

# Ignore log4j initialization messages
if any(line.startswith("log4j: ") for line in lines):
    return None

# Check for Hadoop/YARN errors
hadoop_error = None
for line in lines:
    match = _HADOOP_ERROR_RE.match(line)
    if match:
        hadoop_error = {
            "main_class": match.group("main_class"),
            "message": match.group("message"),
        }
