    match = _SPARK_ERROR_RE.match(line)
    if match:
        spark_error = {
            "main_class": match.group("main_class"),
            "message": match.group("message"),
        }
        break

# Check for stdout/stderr messages
check_stdout = None
for line in lines:
    if line.startswith("Stdout:"):
        check_stdout = "stdout"
        break
    elif line.startswith("Stderr:"):
        check_stdout = "stderr"
        break

# Check for split messages
split = None
for line in lines:
    match = _SPLIT_RE.match(line)
    if match:
        split = {
            "num": int(match.group("num")),
            "of": int(match.group("of")),
            "input_bytes": int(match.group("input_bytes")),
        }
        break

