def update_query_params(uri, params):
    # Parse the URI and extract the query string
    parsed = urlparse.urlparse(uri)
    original_params = parse_qs(parsed.query)

    # Create a dictionary to hold the updated query parameters
    updated_params = {}

    # Iterate through each key-value pair in the `params` dictionary
    for key, value in params.items():
        # If the parameter is already present in the original query string...
        if key in original_params:
            # ...and it has multiple values, add the new value to the list of existing values
            if type(original_params[key]) is list:
                updated_params[key] = original_params[key].append(value)
            # If there's only one original value, replace it with the new value
            else:
                updated_params[key] = [value]
        # If the parameter isn't present in the original query string, add it as a new key-value pair
        else:
            updated_params[key] = [value]

    # Parse the updated query parameters into a URL-encoded string
    updated_query = urlencode(updated_params, doseq=True)

    # Return the original URI with the updated query string
    return urlparse.urlunparse((parsed.scheme, parsed.netloc, parsed.path, parsed.params, updated_query, parsed.fragment))

