"""
Extract the tables from the given SQL statement.

Tables names are extracted from queries with the following structure:
    - select ... from <table> ...
    - update <table> set ...
    - insert into <table> ...
    - delete from <table> ...

:param sql: String. The SQL statement to extract table names from.
:return: Tuple of TableReference namedtuples. The extracted table names from the SQL statement.
"""
# Parse the query and find all instances of "FROM" or "UPDATE".
# This will help us identify the tables in the query.
parsed = sqlparse.parse(sql)[0]
from_tables = []
update_tables = []
insert_tables = []
delete_tables = []
for token in parsed.tokens:
    if token.ttype is Keyword and (
        token.value.lower() == "from" or token.value.lower() == "update"
    ):
        from_tables.append(token)
    elif token.ttype is Keyword and token.value.lower() == "insert":
        insert_tables.append(token)
    elif token.ttype is Keyword and token.value.lower() == "delete":
        delete_tables.append(token)

# Loop through the identified instances of "FROM", "UPDATE", etc.
# and extract the table names from each instance.
tables = []
for f in from_tables:
    for token in f.parent.tokens[1:]:
        if isinstance(token, Identifier):
            tables.append(TableReference(name=token.get_name(), schema=""))
            break
for u in update_tables:
    for token in u.parent.tokens[1:]:
        if isinstance(token, Identifier):
            tables.append(TableReference(name=token.get_name(), schema=""))
            break
for i in insert_tables:
    for token in i.parent.tokens[2:]:
        if isinstance(token, Identifier):
            tables.append(TableReference(name=token.get_name(), schema=""))
            break
for d in delete_tables:
    for token in d.parent.tokens[2:]:
        if isinstance(token, Identifier):
            tables.append(TableReference(name=token.get_name(), schema=""))
            break

return tuple(tables)

