def cast_to_unicode(anything):
    if sys.version_info[0] < 3:
        if isinstance(anything, basestring):
            return unicode(anything)
        elif isinstance(anything, list):
            return [cast_to_unicode(x) for x in anything]
        elif isinstance(anything, dict):
            return {cast_to_unicode(k): cast_to_unicode(v) for k, v in anything.items()}
        else:
            raise TypeError("Unsupported type: {}".format(type(anything)))
    return anything
