"""Saves only the changed data of an Item instance to DynamoDB.

This function updates only the fields that have been modified, rather than pushing the entire item.
This helps prevent accidental overwrites and reduces the amount of data transferred over the network.

:param self: Item. An instance of the Item class.
:return: bool. Returns True if the save operation is successful, False if no save was performed or if the write failed.
"""
try:
    # Check for changes in the item's attributes
    dirty_keys = [
        key for key, value in self.__dict__.items() if getattr(self, key) != value
    ]
    if not dirty_keys:
        return False  # No changes to save
    # Update only the modified fields
    params = {
        "TableName": self.table_name,
        "Key": self.get_primary_key(),
        "AttributeUpdates": {},
    }
    for key in dirty_keys:
        params["AttributeUpdates"][key] = getattr(self, key)
    self.connection.make_request("UpdateItem", params)
except DynamoDBResponseError as e:
    raise e
else:
    return True  # Save successful

