def get_assign_targets_with_attr(self, node: ast.AST) -> List[ast.Attribute]:
    assign_targets = []
    if isinstance(node, (ast.Name, ast.Subscript, ast.Starred)):
        return assign_targets
    elif isinstance(node, (ast.Tuple, ast.List)):
        for elt in node.elts:
            assign_targets.extend(self.get_assign_targets_with_attr(elt))
