def suggest_type(full_text, text_before_cursor):
    # Get the last word in the full text
    last_word = full_text.split()[-1].lower()

    # Get the current scope of the query
    scopes = ['table', 'column']
    for scope in scopes:
        if scope in text_before_cursor:
            break
    else:
        scope = None

    # Determine the completion type based on the last word and current scope
    if scope == 'table':
        if last_word.endswith('.'):
            return [{'type': 'column', 'scope': 'table'}]
        else:
            return [{'type': 'table', 'scope': None}]
    elif scope == 'column':
        if last_word.endswith('('):
            return [{'type': 'function', 'scope': 'column'}]
        else:
            return [{'type': 'column', 'scope': 'table'}]
    else:
        if last_word.startswith(('SELECT ', 'FROM ', 'WHERE ')):
            return [{'type': 'table', 'scope': None}, {'type': 'column', 'scope': 'table'}]
        elif last_word.startswith('INSERT INTO '):
